  "modules": [
    {
      "name": "minisvc.cli",
      "path": "minisvc/cli.py",
      "purpose": "CLI bootstrap that loads settings, opens the repository, initializes the SQLite schema, and reports readiness."
    },
    {
      "name": "minisvc.config",
      "path": "minisvc/config.py",
      "purpose": "Configuration loader for database path and readonly flag from environment variables."
    },
    {
      "name": "minisvc.models",
      "path": "minisvc/models.py",
      "purpose": "Domain model definitions, currently a single Order dataclass."
    },
    {
      "name": "minisvc.audit",
      "path": "minisvc/audit.py",
      "purpose": "Builds in-memory audit event payloads for order actions; does not persist them."
    },
    {
      "name": "minisvc.api.handlers",
      "path": "minisvc/api/handlers.py",
      "purpose": "Request handlers that turn payloads into Order objects, call storage, and shape response bodies."
    },
    {
      "name": "minisvc.api.routes",
      "path": "minisvc/api/routes.py",
      "purpose": "Registers HTTP-style routes against a caller-supplied app object."
    },
    {
      "name": "minisvc.storage.repo",
      "path": "minisvc/storage/repo.py",
      "purpose": "SQLite-backed repository for schema setup, order inserts, and order reads."
    }
  ],
  "entry_points": [
    {
      "identifier": "minisvc.cli:main",
      "kind": "cli",
      "exposed_as": "project.scripts minisvc",
      "purpose": "Initializes storage schema and prints the configured database path."
    },
    {
      "identifier": "minisvc.api.routes:register_routes",
      "kind": "http_registration",
      "purpose": "Attaches POST /orders and GET /orders/<order_id> handlers to an app object."
    },
    {
      "identifier": "minisvc.api.handlers:create_order",
      "kind": "route_handler",
      "route": "POST /orders",
      "purpose": "Creates an Order from request payload data and saves it."
    },
    {
      "identifier": "minisvc.api.handlers:get_order",
      "kind": "route_handler",
      "route": "GET /orders/<order_id>",
      "purpose": "Fetches an order and returns either missing or order data plus an audit event payload."
    }
  ],
  "dependency_edges": [
    {"from": "minisvc.cli", "to": "minisvc.config", "type": "imports"},
